// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

/**
 * @dev Chainlink aggregator interface
 * @author From
 * https://github.com/smartcontractkit/chainlink/blob/develop/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol
 */
interface ChainlinkAggregatorV3Interface {
    function decimals() external view returns (uint8);

    function latestRoundData()
        external
        view
        returns (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 updatedAt,
            uint80 answeredInRound
        );
}

/**
 * @title IPriceFeed
 * @notice Defines the basic interface for a PriceFeed contract.
 */
interface IPriceFeed {
    /**
     * @dev Enum for storing provider type for price feed.
     * @param Chainlink The chainlink price feed.
     * @param API3 The The api3 price feed.
     */
    enum ProviderType {
        Chainlink,
        Pyth
    }

    /**
     * @dev Struct for storing information for price oracle.
     * @param oracleAddress The oracle address.
     * @param providerType The provider type.
     * @param timeoutSeconds The maximum period that lasts a stale price.
     * @param decimals The decimal precision of price oracle.
     * @param isEthIndexed The flag to indicate whether to fetch price based on ETH.
     * @param additionalData The additional data required by the specific oracle type.
     */
    struct OracleRecord {
        address oracleAddress;
        ProviderType providerType;
        uint256 timeoutSeconds;
        uint256 decimals;
        bool isEthIndexed;
        bytes32 additionalData;
        uint256 maxConfidenceInterval;
    }

    struct PriceRecord {
        uint256 scaledPrice;
        uint256 timestamp;
        uint256 lastUpdated;
    }

    /// @dev Error emitted when setting up fallback oracle without no existing primary oracle.
    error PriceFeed__ExistingOracleRequired();

    /// @dev Error emitted when the decimal precision of price oracle is zero.
    error PriceFeed__InvalidDecimalsError();

    /// @dev Error emitted when the fetched price for a specific token is zero.
    /// @param _token The token address to fetch price.
    error PriceFeed__InvalidOracleResponseError(address _token);

    /// @dev Error emitted when the caller is not Timelock contract.
    error PriceFeed__TimelockOnlyError();

    /// @dev Error emitted when returning oracle address for unknown asset.
    error PriceFeed__UnknownAssetError();

    /// @dev Error emitted when the price feed is missing Pyth feed id.
    error PriceFeed__MissingPythFeedId();

    /**
     * @dev Emitted when new oracle for a specific asset is registered.
     * @param _token The asset address.
     * @param _oracleAddress The oracle address.
     * @param _isEthIndexed The flag to indicate whether to fetch price based on ETH.
     * @param _isFallback The flag to indicate whether to set as fallback oracle.
     */
    event NewOracleRegistered(
        address _token, address _oracleAddress, bool _isEthIndexed, bool _isFallback
    );

    /**
     * @notice Fetches the price for an asset from a previously configured oracle.
     * @dev Callers:
     *    - BorrowerOperations.openTrenBox()
     *    - BorrowerOperations.adjustTrenBox()
     *    - BorrowerOperations.closeTrenBox()
     *    - TrenBoxManagerOperations.liquidateTrenBoxes()
     *    - TrenBoxManagerOperations.batchLiquidateTrenBoxes()
     *    - TrenBoxManagerOperations.redeemCollateral()
     * @param _token The asset address.
     */
    function fetchPrice(address _token) external view returns (uint256);

    /**
     * @notice Sets an oracle information for a specific asset.
     * @param _token The asset address.
     * @param _oracle The oracle address.
     * @param _type The provider type.
     * @param _timeoutSeconds The maximum period that lasts a stale price.
     * @param _isEthIndexed The flag to indicate whether to fetch price based on ETH.
     * @param _isFallback The flag to indicate whether to set as fallback oracle.
     * @param _additionalData The additional data required by the oracle provider.
     */
    function setOracle(
        address _token,
        address _oracle,
        ProviderType _type,
        uint256 _timeoutSeconds,
        bool _isEthIndexed,
        bool _isFallback,
        bytes32 _additionalData,
        uint256 _maxConfidenceInterval
    )
        external;
}

contracts/interfaces/ISortedTrenBoxes.so.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

/**
 * @title ISortedTrenBoxes
 * @notice Defines the basic interface for SortedTrenBoxes contract.
 */
interface ISortedTrenBoxes {
    // --- Structs ---

    /**
     * @dev Struct for storing Node information.
     * @param exists The existence indicator.
     * @param nextId The Id of next Node (smaller NICR) in the list.
     * @param prevId The Id of previous Node (larger NICR) in the list.
     */
    struct Node {
        bool exists;
        address nextId;
        address prevId;
    }

    /**
     * @dev Struct for storing Node list.
     * @param head The head of the list. Also the Node in the list with the largest NICR.
     * @param tail The tail of the list. Also the Node in the list with the smallest NICR.
     * @param size The current size of the list.
     * @param nodes The mapping from depositor address to its Node in the list.
     */
    struct TrenBoxesList {
        address head;
        address tail;
        uint256 size;
        mapping(address depositor => Node node) nodes;
    }

    // --- Events ---

    /**
     * @dev Emitted when the new Node is added to the list.
     * @param _asset The address of collateral asset.
     * @param _id The new Node's id.
     * @param _NICR The new Node's NICR.
     */
    event NodeAdded(address indexed _asset, address _id, uint256 _NICR);

    /**
     * @dev Emitted when a Node is removed from the list.
     * @param _asset The address of collateral asset.
     * @param _id The Node's id.
     */
    event NodeRemoved(address indexed _asset, address _id);

    // --- Errors ---

    /// @dev Error emitted when the list does not contain the specific Node.
    error SortedTrenBoxes__ListDoesNotContainNode();

    /// @dev Error emitted when the list already contains the specific Node.
    error SortedTrenBoxes__ListAlreadyContainsNode();

    /// @dev Error emitted when the specific Node's id is zero.
    error SortedTrenBoxes__IdCannotBeZeroAddress();

    /// @dev Error emitted when the specific Node's NICR is zero.
    error SortedTrenBoxes__NICRMustBeGreaterThanZero();

    /// @dev Error emitted when the caller is not TrenBoxManager contract.
    error SortedTrenBoxes__CallerMustBeTrenBoxManager();

    /// @dev Error emitted when the caller is neither BorrowerOperations nor
    /// TrenBoxManager contract.
    error SortedTrenBoxes__CallerMustBeBorrowerOperationsOrTrenBoxManager();

    // --- Functions ---

    /**
     * @notice Adds a new Node to the list.
     * @param _asset The address of collateral asset.
     * @param _id The Node's id.
     * @param _NICR The Node's NICR.
     * @param _prevId The Id of previous node for the insert position.
     * @param _nextId The Id of next node for the insert position.
     */
    function insert(
        address _asset,
        address _id,
        uint256 _NICR,
        address _prevId,
        address _nextId
    )
        external;

    /**
     * @notice Removes a Node from the list.
     * @param _asset The address of collateral asset.
     * @param _id The Node's id.
     */
    function remove(address _asset, address _id) external;

    /**
     * @notice Reinserts the Node at a new position based on its new NICR.
     * @param _asset The address of collateral asset.
     * @param _id The Node's id.
     * @param _newNICR The Node's new NICR.
     * @param _prevId The Id of previous Node for the new insert position.
     * @param _nextId The Id of next Node for the new insert position.
     */
    function reInsert(
        address _asset,
        address _id,
        uint256 _newNICR,
        address _prevId,
        address _nextId
    )
        external;

    /**
     * @notice Checks if the list contains a Node.
     * @param _asset The address of collateral asset.
     * @param _id The Node's id.
     */
    function contains(address _asset, address _id) external view returns (bool);

    /**
     * @notice Checks if the list is empty.
     * @param _asset The address of collateral asset.
     */
    function isEmpty(address _asset) external view returns (bool);

    /**
     * @notice Returns the current size of the list.
     * @param _asset The address of collateral asset.
     */
    function getSize(address _asset) external view returns (uint256);

    /**
     * @notice Returns the first Node (with the largest NICR) in the list.
     * @param _asset The address of collateral asset.
     */
    function getFirst(address _asset) external view returns (address);

    /**
     * @notice Returns the last Node (with the smallest NICR) in the list.
     * @param _asset The address of collateral asset.
     */
    function getLast(address _asset) external view returns (address);

    /**
     * @notice Returns the next Node (with a smaller NICR) in the list for
     * a given Node.
     * @param _asset The address of collateral asset.
     * @param _id The Node's id.
     */
    function getNext(address _asset, address _id) external view returns (address);

    /**
     * @notice Returns the previous Node (with a larger NICR) in the list for
     * a given Node.
     * @param _asset The address of collateral asset.
     * @param _id The Node's id.
     */
    function getPrev(address _asset, address _id) external view returns (address);

    /**
     * @notice Checks if a pair of Nodes is a valid insertion point for
     * a new Node with the given NICR.
     * @param _asset The address of collateral asset.
     * @param _NICR The Node's NICR.
     * @param _prevId The Id of previous Node for the insert position.
     * @param _nextId The Id of next Node for the insert position.
     */
    function validInsertPosition(
        address _asset,
        uint256 _NICR,
        address _prevId,
        address _nextId
    )
        external
        view
        returns (bool);

    /**
     * @notice Finds the insert position for a new Node with the given NICR.
     * @param _asset The address of collateral asset.
     * @param _NICR The Node's NICR.
     * @param _prevId The Id of previous node for the insert position.
     * @param _nextId The Id of next node for the insert position.
     */
    function findInsertPosition(
        address _asset,
        uint256 _NICR,
        address _prevId,
        address _nextId
    )
        external
        view
        returns (address, address);
}

contracts/interfaces/ISwapManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

/// @title ISwapManager
/// @notice Defines the basic interface for SwapManager.
interface ISwapManager {
    /**
     * @dev Configuration for swapping collateral
     * @param swapper The address of swapper contract
     * @param underlyingAsset The address of underlying asset of collateral after swap
     * @param fee The amount of fee to pay for swap
     * @param stablecoin The address of stablecoin which using as middle stage to get XY
     * @param directSwap The index that show possibility to swap without or with middle stage
     * (stablecoin) to get XY
     * @param pathFee The amount of fee to pay for swap with middle stage
     */
    struct SwapConfig {
        address swapper;
        address underlyingAsset;
        uint256 fee;
        bool directSwap;
        address stablecoin;
        uint256[] pathFee;
    }

    struct DebtSwapConfig {
        uint256 fee;
        bool directSwap;
        address stablecoin;
        uint256[] pathFee;
    }

    /// @dev Thrown when the caller is not BorrowerOperations contract.
    error SwapManager__CallerIsNotBorrowerOperations();

    /// @dev Thrown when the caller is not TrenBoxStorage or BorrowerOperations or StabilityPool
    /// contract.
    error SwapManager__CallerIsNotVerified();

    /// @dev Thrown when the caller is not FlashLoan contract.
    error SwapManager__CallerIsNotFlashLoan();

    /// @dev Thrown when one or more provided addresses are zero addresses.
    error SwapManager__ZeroAddress();

    /// @dev Thrown when the config should be set.
    error SwapManager__ConfigShouldBeSetFirst(address coll);

    /// @dev Thrown when the config is not set.
    error SwapManager__ConfigNotSet(address asset);

    /// @dev Thrown when the arrays are not the same length.
    error SwapManager__ArrayMismatch();

    /// @dev Thrown when the path fee length is invalid (more or less than 2).
    error SwapManager__InvalidPathFeeLength();

    /// @dev Thrown when the renounce ownership is disabled.
    error SwapManager__RenounceOwnershipDisabled();

    /// @dev Emitted when the new config is set.
    event SetConfig(address indexed asset, SwapConfig config, DebtSwapConfig debtConfig);

    /// @dev Emitted when the config is updated.
    event UpdateConfig(address indexed asset, SwapConfig config, DebtSwapConfig debtConfig);

    /// @dev Emitted when the config is removed.
    event RemoveConfig(address indexed asset);

    /// @dev Emitted when the new router is set.
    event NewRouterSet(address indexed router);

    /// @dev Emitted when the collateral is staked.
    event StakedCollateral(address indexed coll, uint256 collAmount);

    /// @dev Emitted when the collateral is unstaked.
    event UnstakedCollateral(address indexed coll, uint256 collAmount);

    /// @dev Emitted when the collateral is swapped to XY.
    event Swap(
        address indexed caller,
        address indexed coll,
        uint256 collAmountIn,
        address indexed underlyingAsset,
        uint256 debtAmountOut
    );

    /**
     * @notice Swaps collateral to XY with Flashloan
     * @dev Only Flashloan contract can call
     * @param coll The address of collateral asset
     * @param collAmount The amount of collateral to swap
     * @param debtExpected The expected amount of XY to get after swap
     * @param recipient The address of recipient
     */
    function swap(
        address coll,
        uint256 collAmount,
        uint256 debtExpected,
        address recipient
    )
        external;

    /**
     * @notice Stakes collateral
     * @dev Only BorrowerOperations contract can call
     * As an example with Curve protocol, we need to stake LP into Gauge contract to get rewards in
     * CRV token
     * @param coll The address of collateral asset
     * @param collAmount The amount of collateral to stake
     */
    function stake(address coll, uint256 collAmount) external;

    /**
     * @notice Unstakes collateral
     * @dev Only TrenBoxStorage contract can call
     * We just unstake LP token from Gauge without claiming rewards
     * @param coll The address of collateral asset
     * @param collAmount The amount of collateral to unstake
     */
    function unstake(address coll, uint256 collAmount) external;
}

contracts/interfaces/ITrenBoxManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

/**
 * @title ITrenBoxManager
 * @notice Defines the basic interface for TrenBoxManager contract.
 */
interface ITrenBoxManager {
    // Enums
    // ------------------------------------------------------------------------------------------------------------

    /**
     * @dev Enum for storing TrenBox status.
     * @param nonExistent The non-existence status .
     * @param active The active status.
     * @param closedByOwner The closed status by owner.
     * @param closedByLiquidation The closed status by liquidation.
     * @param closedByRedistribution The closed status by redistribution.
     */
    enum Status {
        nonExistent,
        active,
        closedByOwner,
        closedByLiquidation,
        closedByRedistribution
    }

    /**
     * @dev Enum for storing operation type by TrenBoxManagerOperations contract.
     * @param applyPendingRewards The operation that adds pending rewards to the TrenBox.
     * @param liquidateInNormalMode The operation that closes the TrenBox by liquidation
     * under normal mode.
     * @param liquidateInRecoveryMode The operation that closes the TrenBox by liquidation
     * under recovery mode.
     * @param redistributeCollateral The operation that closes the TrenBox by redistribution.
     */
    enum TrenBoxManagerOperation {
        applyPendingRewards,
        liquidateInNormalMode,
        liquidateInRecoveryMode,
        redistributeCollateral
    }

    // Structs
    // ----------------------------------------------------------------------------------------------------------

    /**
     * @dev Struct for storing TrenBox information.
     * @param debt The debt token amount.
     * @param coll The collateral amount.
     * @param stake The stake amount.
     * @param status The current status.
     * @param arrayIndex The index in the owner array.
     */
    struct TrenBox {
        uint256 debt;
        uint256 coll;
        uint256 stake;
        Status status;
        uint128 arrayIndex;
    }

    /**
     * @dev Struct for storing the collateral and debt token snapshots for a given active TrenBox.
     * @param asset The snapshot of collateral asset.
     * @param debt The snapshot of debt token.
     */
    struct RewardSnapshot {
        uint256 asset;
        uint256 debt;
    }

    // Events
    // -----------------------------------------------------------------------------------------------------------

    /**
     * @dev Emitted when the timestamp of last fee operation is updated.
     * @param _asset The address of collateral asset.
     * @param _lastFeeOpTime The timestamp of latest fee operation.
     */
    event LastFeeOpTimeUpdated(address indexed _asset, uint256 _lastFeeOpTime);

    /**
     * @dev Emitted when the total staked amount for a specific collateral is updated.
     * @param _asset The address of collateral asset.
     * @param _newTotalStakes The new total staked amount.
     */
    event TotalStakesUpdated(address indexed _asset, uint256 _newTotalStakes);

    /**
     * @dev Emitted when the system snapshot is updated.
     * @param _asset The address of collateral asset.
     * @param _totalStakesSnapshot The total stakes snapshot.
     * @param _totalCollateralSnapshot The total collateral snapshot.
     */
    event SystemSnapshotsUpdated(
        address indexed _asset, uint256 _totalStakesSnapshot, uint256 _totalCollateralSnapshot
    );

    /**
     * @dev Emitted when the accumulated liquidation rewards per unit staked are updated.
     * @param _asset The address of collateral asset.
     * @param _L_Coll The liquidated collateral.
     * @param _L_Debt The liquidated debt.
     */
    event LTermsUpdated(address indexed _asset, uint256 _L_Coll, uint256 _L_Debt);

    /**
     * @dev Emitted when the reward snapshot is updated.
     * @param _asset The address of collateral asset.
     * @param _L_Coll The liquidated collateral.
     * @param _L_Debt The liquidated debt.
     */
    event TrenBoxSnapshotsUpdated(address indexed _asset, uint256 _L_Coll, uint256 _L_Debt);

    /**
     * @dev Emitted when the owner of TrenBox is removed in owners array.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _newIndex The new array index.
     */
    event TrenBoxIndexUpdated(address indexed _asset, address _borrower, uint256 _newIndex);

    /**
     * @dev Emitted when the specific TrenBox is updated.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _debt The new debt amount.
     * @param _coll The new collateral amount.
     * @param _stake The new stake amount.
     * @param _operation The operation type.
     */
    event TrenBoxUpdated(
        address indexed _asset,
        address indexed _borrower,
        uint256 _debt,
        uint256 _coll,
        uint256 _stake,
        TrenBoxManagerOperation _operation
    );

    // Custom Errors
    // ----------------------------------------------------------------------------------------------------

    /// @dev Error emitted when there is only one or zero TrenBox.
    error TrenBoxManager__OnlyOneTrenBox();

    /// @dev Error emitted when the caller is not TrenBoxManagerOperations contract.
    error TrenBoxManager__OnlyTrenBoxManagerOperations();

    /// @dev Error emitted when the caller is not BorrowerOperations contract.
    error TrenBoxManager__OnlyBorrowerOperations();

    /// @dev Error emitted when the caller is neither SwapManager
    /// nor BorrowerOperations.
    error TrenBoxManager__OnlyBorrowerOperationsOrSwapManager();

    /// @dev Error emitted when the caller is neither TrenBoxManagerOperations
    /// nor BorrowerOperations.
    error TrenBoxManager__OnlyTrenBoxManagerOperationsOrBorrowerOperations();

    // Functions
    // --------------------------------------------------------------------------------------------------------

    /**
     * @notice Returns the nominal collateral ratio (ICR) of a given TrenBox without the price.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getNominalICR(address _asset, address _borrower) external view returns (uint256);

    /**
     * @notice Returns the current collateral ratio (ICR) of a given TrenBox.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _price The price of collateral asset.
     */
    function getCurrentICR(
        address _asset,
        address _borrower,
        uint256 _price
    )
        external
        view
        returns (uint256);

    /**
     * @notice Returns the borrower's pending accumulated collateral reward
     * earned by their stake.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getPendingAssetReward(
        address _asset,
        address _borrower
    )
        external
        view
        returns (uint256);

    /**
     * @notice Returns the borrower's pending accumulated debt token reward
     * earned by their stake.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getPendingDebtTokenReward(
        address _asset,
        address _borrower
    )
        external
        view
        returns (uint256);

    /**
     * @notice Returns whether the borrower has pending rewards.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function hasPendingRewards(address _asset, address _borrower) external view returns (bool);

    /**
     * @notice Returns the borrower's entire debt and collateral balances
     * with pending rewards.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getEntireDebtAndColl(
        address _asset,
        address _borrower
    )
        external
        view
        returns (uint256 debt, uint256 coll, uint256 pendingDebtReward, uint256 pendingCollReward);

    /**
     * @notice Returns whether the specific TrenBox is active or not.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function isTrenBoxActive(address _asset, address _borrower) external view returns (bool);

    /**
     * @notice Returns the total collateral ratio for a specific collaterl asset.
     * @param _asset The address of collateral asset.
     * @param _price The price of collateral asset.
     */
    function getTCR(address _asset, uint256 _price) external view returns (uint256);

    /**
     * @notice Checks whether the current mode is Recovery Mode or not.
     * @param _asset The address of collateral asset.
     * @param _price The price of collateral asset.
     */
    function checkRecoveryMode(address _asset, uint256 _price) external view returns (bool);

    /**
     * @notice Returns the borrowing fee rate for a specific collateral asset.
     * @param _asset The address of collateral asset.
     */
    function getBorrowingRate(address _asset) external view returns (uint256);

    /**
     * @notice Returns the borrowing fee amount for a given debt amount.
     * @param _asset The address of collateral asset.
     * @param _debtTokenAmount The amount of debt tokens to borrow.
     */
    function getBorrowingFee(
        address _asset,
        uint256 _debtTokenAmount
    )
        external
        view
        returns (uint256);

    /**
     * @notice Returns the TrenBox owner based on array index.
     * @param _asset The address of collateral asset.
     * @param _index The array index.
     */
    function getTrenBoxFromTrenBoxOwnersArray(
        address _asset,
        uint256 _index
    )
        external
        view
        returns (address);

    /**
     * @notice Returns the net debt amount excluded gas compensation.
     * @param _asset The address of collateral asset.
     * @param _debt The amount of debt tokens.
     */
    function getNetDebt(address _asset, uint256 _debt) external view returns (uint256);

    /**
     * @notice Returns the number of TrenBox owners for a specific collateral asset.
     * @param _asset The address of collateral asset.
     */
    function getTrenBoxOwnersCount(address _asset) external view returns (uint256);

    /**
     * @notice Returns the TrenBox status for a specific borrower.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getTrenBoxStatus(address _asset, address _borrower) external view returns (uint256);

    /**
     * @notice Returns the TrenBox stake for a specific borrower.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getTrenBoxStake(address _asset, address _borrower) external view returns (uint256);

    /**
     * @notice Returns the TrenBox debt balance for a specific borrower.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getTrenBoxDebt(address _asset, address _borrower) external view returns (uint256);

    /**
     * @notice Returns the TrenBox collateral balance for a specific borrower.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function getTrenBoxColl(address _asset, address _borrower) external view returns (uint256);

    /**
     * @notice Adds a specific borrower to the owner array.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function addTrenBoxOwnerToArray(
        address _asset,
        address _borrower
    )
        external
        returns (uint256 index);

    /**
     * @notice Adds the pending debt and collateral rewards to the TrenBox.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function applyPendingRewards(address _asset, address _borrower) external;

    /**
     * @notice Moves the TrenBox's pending debt and collateral rewards to active TrenBoxStorage.
     * @param _asset The address of collateral asset.
     * @param _debtTokenAmount The amount of debt tokens to move.
     * @param _assetAmount The amount of collateral asset to move.
     */
    function movePendingTrenBoxRewardsFromLiquidatedToActive(
        address _asset,
        uint256 _debtTokenAmount,
        uint256 _assetAmount
    )
        external;

    /**
     * @notice Updates the borrower's rewards snapshot.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function updateTrenBoxRewardSnapshots(address _asset, address _borrower) external;

    /**
     * @notice Updates the borrower's stake based on their latest collateral.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function updateStakeAndTotalStakes(
        address _asset,
        address _borrower
    )
        external
        returns (uint256);

    /**
     * @notice Removes the borrower's stake amount from total staked amount.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function removeStake(address _asset, address _borrower) external;

    /**
     * @notice Adds distributed collateral and debt rewards to the running totals.
     * @param _asset The address of collateral asset.
     * @param _debt The debt amount to redistribute.
     * @param _coll The collateral amount to redistribute.
     * @param _debtToOffset The debt amount to offset.
     * @param _collToSendToStabilityPool The collateral amount to send to the Stability Pool.
     */
    function redistributeDebtAndColl(
        address _asset,
        uint256 _debt,
        uint256 _coll,
        uint256 _debtToOffset,
        uint256 _collToSendToStabilityPool
    )
        external;

    /**
     * @notice Updates system snapshot excluding collateral remainder.
     * @param _asset The address of collateral asset.
     * @param _collRemainder The collateral remainder.
     */
    function updateSystemSnapshots_excludeCollRemainder(
        address _asset,
        uint256 _collRemainder
    )
        external;

    /**
     * @notice Closes a specific borrower's TrenBox.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function closeTrenBox(address _asset, address _borrower) external;

    /**
     * @notice Closes a specific borrower's TrenBox by liquidation.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     */
    function closeTrenBoxLiquidation(address _asset, address _borrower) external;

    /**
     * @notice Closes a specific borrower's TrenBox by redistribution.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _debtTokenGasCompensationToBurn The gas compensation to burn.
     */
    function closeTrenBoxRedistribution(
        address _asset,
        address _borrower,
        uint256 _debtTokenGasCompensationToBurn
    )
        external;

    /**
     * @notice Sends gas compensation to the liquidator.
     * @param _asset The address of collateral asset.
     * @param _liquidator The liquidator address.
     * @param _debtTokenAmount The debt token amount of gas compensation.
     * @param _assetAmount The collateral amount of gas compensation.
     */
    function sendGasCompensation(
        address _asset,
        address _liquidator,
        uint256 _debtTokenAmount,
        uint256 _assetAmount
    )
        external;

    /**
     * @notice Sets the TrenBox's status.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _num The enum status to set.
     */
    function setTrenBoxStatus(address _asset, address _borrower, uint256 _num) external;

    /**
     * @notice Increases the TrenBox's collateral balance.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _collIncrease The collateral amount to increase.
     */
    function increaseTrenBoxColl(
        address _asset,
        address _borrower,
        uint256 _collIncrease
    )
        external
        returns (uint256);

    /**
     * @notice Decreases the TrenBox's collateral balance.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _collDecrease The collateral amount to decrease.
     */
    function decreaseTrenBoxColl(
        address _asset,
        address _borrower,
        uint256 _collDecrease
    )
        external
        returns (uint256);

    /**
     * @notice Increases the TrenBox's debt token balance.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _debtIncrease The debt token amount to increase.
     */
    function increaseTrenBoxDebt(
        address _asset,
        address _borrower,
        uint256 _debtIncrease
    )
        external
        returns (uint256);

    /**
     * @notice Decreases the TrenBox's debt token balance.
     * @param _asset The address of collateral asset.
     * @param _borrower The borrower address.
     * @param _debtDecrease The deb token amount to decrease.
     */
    function decreaseTrenBoxDebt(
        address _asset,
        address _borrower,
        uint256 _debtDecrease
    )
        external
        returns (uint256);

    function getTrenBoxOwners(address _asset) external view returns (address[] memory);
}

contracts/interfaces/ITrenBoxStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.23;

/**
 * @title ITrenBoxStorage
 * @notice Defines the basic interface for TrenBoxStorage contract.
 */
interface ITrenBoxStorage {
    // ------------------------------------------ Structs -----------------------------------------

    /// @dev Struct for storing debt balances of a specific collateral asset.
    /// @param active The entire debt of all active TrenBoxes.
    /// @param liquidated The entire debt of all liquidated TrenBoxes.
    struct DebtBalances {
        uint256 active;
        uint256 liquidated;
    }

    /// @dev Struct for storing balances of a specific collateral asset.
    /// @param active The entire collateral amount of all active TrenBoxes.
    /// @param liquidated The entire collateral amount of all liquidated TrenBoxes.
    /// @param claimable The entire collateral amount of all liquidated TrenBoxes that can be
    /// claimed by user.
    struct CollBalances {
        uint256 active;
        uint256 liquidated;
        uint256 claimable;
    }

    // ------------------------------------------ Events ------------------------------------------

    /**
     * @dev Emitted when the active collateral balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new active collateral balance.
     */
    event ActiveCollateralBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the active debt balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new active debt balance.
     */
    event ActiveDebtBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the liquidated collateral balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new liquidated collateral balance.
     */
    event LiquidatedCollateralBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the liquidated debt balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new liquidated debt balance.
     */
    event LiquidatedDebtBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when the claimable collateral balance is updated.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new claimable collateral balance.
     */
    event ClaimableCollateralBalanceUpdated(address indexed _collateral, uint256 _newBalance);

    /**
     * @dev Emitted when collateral is sent.
     * @param _to The address of the user which get collateral amount.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount of collateral sent.
     */
    event CollateralSent(address indexed _to, address indexed _collateral, uint256 _amount);

    /**
     * @dev Emitted when the user claimable collateral balance is updated.
     * @param _account The address of the user.
     * @param _collateral The address of the collateral asset.
     * @param _newBalance The new user claimable collateral balance.
     */
    event UserClaimableCollateralBalanceUpdated(
        address indexed _account, address indexed _collateral, uint256 _newBalance
    );

    // ------------------------------------------ Custom Errors -----------------------------------

    /**
     * @dev Thrown when contract is not authorized.
     */
    error TrenBoxStorage__NotAuthorizedContract();

    /**
     * @dev Thrown when caller is not TrenBoxManager contract.
     */
    error TrenBoxStorage__TrenBoxManagerOnly();

    /**
     * @dev Thrown when caller is not BorrowerOperations contract.
     */
    error TrenBoxStorage__BorrowerOperationsOnly();

    /**
     * @dev Thrown when caller is not BorrowerOperations nor SwapManager contract.
     */
    error TrenBoxStorage__BorrowerOperationsOrSwapManagerOnly();

    /**
     * @dev Thrown when caller is not BorrowerOperations nor TrenBoxManager contract.
     */
    error TrenBoxStorage__BorrowerOperationsOrTrenBoxManagerOnly();

    /**
     * @dev Thrown when caller is not TrenBoxManagerOperations contract.
     */
    error TrenBoxStorage__TrenBoxManagerOperationsOnly();

    /**
     * @dev Thrown when there is no claimable collateral available.
     */
    error TrenBoxStorage__NoClaimableCollateral();

    // ------------------------------------------ Functions ---------------------------------------

    /**
     * @notice Returns the active collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getActiveCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the active debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getActiveDebtBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the liquidated collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getLiquidatedCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the liquidated debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getLiquidatedDebtBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns sum of active and liquidated debt for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getTotalDebtBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns sum of active and liquidated amount of a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getTotalCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the claimable collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     */
    function getClaimableCollateralBalance(address _collateral) external view returns (uint256);

    /**
     * @notice Returns the claimable collateral balance for a specific user.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user.
     */
    function getUserClaimableCollateralBalance(
        address _collateral,
        address _account
    )
        external
        view
        returns (uint256);

    /**
     * @notice Increases the active debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to increase the debt balance.
     */
    function increaseActiveDebt(address _collateral, uint256 _amount) external;

    /**
     * @notice Decreases the active debt balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to decrease the debt balance.
     */
    function decreaseActiveDebt(address _collateral, uint256 _amount) external;

    /**
     * @notice Increases the active balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to increase the debt balance.
     */
    function increaseActiveCollateral(address _collateral, uint256 _amount) external;

    /**
     * @notice Decreases the active balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to decrease the collateral balance.
     */
    function decreaseActiveCollateral(address _collateral, uint256 _amount) external;

    /**
     * @notice Update appropriate data for a specific collateral.
     * @param data The data to update.
     */
    function update(bytes memory data) external;

    /**
     * @notice Updates the active and liquidated debt and collateral balances.
     * @param _collateral The address of the collateral asset.
     * @param _debtAmount The amount to decrease the debt balance.
     * @param _collAmount The amount to decrease the collateral balance.
     * @param _isActiveIncrease The indicator that shows increasing or decreasing of active
     * balances.
     */
    function updateDebtAndCollateralBalances(
        address _collateral,
        uint256 _debtAmount,
        uint256 _collAmount,
        bool _isActiveIncrease
    )
        external;

    /**
     * @notice Updates the entire and user claimable balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user.
     * @param _amount The amount to update the claimable balance.
     */
    function updateUserAndEntireClaimableBalance(
        address _collateral,
        address _account,
        uint256 _amount
    )
        external;

    /**
     * @notice Increases the claimable collateral balance for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _amount The amount to increase the claimable collateral balance.
     */
    function increaseClaimableCollateral(address _collateral, uint256 _amount) external;

    /**
     * @notice Updates the claimable collateral balance of the user for a specific collateral asset.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user.
     * @param _amount The amount to update the claimable balance.
     */
    function updateUserClaimableBalance(
        address _collateral,
        address _account,
        uint256 _amount
    )
        external;

    /**
     * @notice Sends amount of active collateral from contract to user.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user to send.
     * @param _amount The amount of the collateral to send.
     */
    function sendCollateral(address _collateral, address _account, uint256 _amount) external;

    /**
     * @notice Sends amount of claimable collateral from contract to user.
     * @param _collateral The address of the collateral asset.
     * @param _account The address of the user to send.
     */
    function claimCollateral(address _collateral, address _account) external;
}
